const nav:{id:Tab;label:string;icon:any}[]=[{id:'overview',label:'Your workspace',icon:Layers3},{id:'chat',label:'Conversation',icon:MessageSquare},{id:'plan',label:'Plan builder',icon:GitBranch},{id:'activity',label:'Execution center',icon:Activity},{id:'insights',label:'Delivery insights',icon:Gauge},{id:'memory',label:'Project memory',icon:BookOpen},{id:'playbooks',label:'Playbooks & agents',icon:Zap},{id:'usage',label:'Models & usage',icon:Command},{id:'teach',label:'Teach assistant',icon:WandSparkles},{id:'quality',label:'Quality lab',icon:Target},{id:'settings',label:'Autonomy & calendar',icon:ShieldCheck}];
