  async function loadItems(){setArtifacts((await api.get(`${ROOT}/items`,{params:{project_id:projectId}})).data.items);}
  async function refresh(){const [a,b,c,d]=await Promise.all([api.get(`${ROOT}/items`,{params:{project_id:projectId}}),api.get(`${ROOT}/insights`,{params:{project_id:projectId}}),api.get(`${ROOT}/metrics`,{params:{project_id:projectId}}),operatorApi.runs(projectId)]);setArtifacts(a.data.items);setInsights(b.data);setMetrics(c.data);setRuns(d.data.items);}
  function openRun(run:OperatorRun){setActiveRun(run);setRuns(old=>[run,...old.filter(r=>r.id!==run.id)]);setTab('activity');if(run.plan)setDraft({...run.plan,clarification:null});}
  async function save(kind:string,title:string,payload:Row,row?:Row){const data={project_id:projectId,kind,title,payload,...(row?{revision:row.revision}:{})};await (row?api.put(`${ROOT}/items/${row.id}`,data):api.post(`${ROOT}/items`,data));await loadItems();setNotice(kind==='teaching'?'Submitted for project administrator review.':'Saved to your private project workspace.');}
  useEffect(()=>{const abort=new AbortController();api.get('/project-management/projects',{signal:abort.signal}).then(r=>{const data=Array.isArray(r.data)?r.data:r.data.items || [];setProjects(data);if(!projectId&&data[0])setProjectId(data[0].id);}).catch(e=>{if(!abort.signal.aborted)setError(errorText(e));});return()=>abort.abort();},[]);
  useEffect(()=>{
    if(!projectId)return;const token=++epoch.current,abort=new AbortController();setContext({tasks:[],collaborators:[],sprints:[]});setArtifacts([]);setRuns([]);setActiveRun(null);setRevision(null);setImpact(null);setSetup(null);setSelected(Number(params.get('task'))?[Number(params.get('task'))]:[]);setPolicy(defaults);setError('');setEvents([]);setGuided(null);setLocalMessages([]);setLastQuestion('');
    const get=(path:string)=>api.get(path,{params:{project_id:projectId},signal:abort.signal});
    Promise.all([get('/ai-operator/local-context'),get(`${ROOT}/items`),get(`${ROOT}/insights`),get(`${ROOT}/metrics`),operatorApi.runs(projectId)]).then(([a,b,c,d,e])=>{
      if(token!==epoch.current||abort.signal.aborted)return;setContext(a.data);setArtifacts(b.data.items);setInsights(c.data);setMetrics(d.data);setRuns(e.data.items);
      const p=b.data.items.find((r:Row)=>r.kind==='policy');setPolicy(p?.payload || defaults);
    }).catch(e=>{if(!abort.signal.aborted)setError(errorText(e));});
    return()=>abort.abort();
  },[projectId]);
  useEffect(()=>{if(!project)return;const abort=new AbortController();operatorApi.providers(project.workspace_id || undefined).then(r=>{if(!abort.signal.aborted)setAvailable(r.data.items.filter(p=>p.enabled&&p.data_sharing_allowed&&p.has_key).map(p=>p.provider));}).catch(()=>setAvailable([]));return()=>abort.abort();},[project?.id]);
  useEffect(()=>{
    if(!projectId||tab!=='activity')return;let stopped=false;
    const timer=setInterval(async()=>{try{const data=(await operatorApi.runs(projectId)).data.items;if(stopped)return;setRuns(data);if(activeRun){const current=data.find(r=>r.id===activeRun.id);if(current)setActiveRun(current);}}catch{/* A transient poll does not replace the visible run. */}},4000);
    return()=>{stopped=true;clearInterval(timer);};
  },[tab,projectId,activeRun?.id]);
  useEffect(()=>{
    if(!activeRun)return;let stopped=false;if(cursor.current.id!==activeRun.id){cursor.current={id:activeRun.id,after:0};setEvents([]);}
    async function poll(){try{const r=await operatorApi.events(activeRun!.id,cursor.current.after);if(stopped)return;cursor.current.after=r.data.next_cursor;setEvents(old=>[...old,...r.data.items.filter(e=>!old.some(o=>o.id===e.id))].slice(-100));}catch{/* Run state remains available when event polling reconnects. */}}
    void poll();const timer=setInterval(poll,4000);return()=>{stopped=true;clearInterval(timer);};
  },[activeRun?.id]);
