          const result=(await api.post(`${ROOT}/plans/preview`,{project_id:projectId,plan,request_key:crypto.randomUUID(),mode,input_mode:voiceOrigin.current?'voice':'text',...(revising?{parent_run_id:activeRun!.id,parent_plan_hash:activeRun!.plan_hash}:{})})).data;
