  async function previewPlan(){const r=(await api.post(`${ROOT}/plans/preview`,{project_id:projectId,plan:draft,request_key:crypto.randomUUID(),mode,...(revision?{parent_run_id:revision.id,parent_plan_hash:revision.plan_hash}:{})})).data;setRevision(null);openRun(r);}
  function addStep(){const id=selected[0] || context.tasks[0]?.id;if(!id){setError('Create or select a task before adding a step.');return;}setDraft(p=>({...p,steps:[...p.steps,{tool:'update_task',task_id:id,changes:{priority:'High'}}]}));}
